import { 
    initializeApp 
} from "firebase/app";
import { 
    getFirestore, 
    doc, 
    setDoc, 
    serverTimestamp, 
    collection, 
    query,      
    getDocs,    
    orderBy,    
    deleteDoc, 
    updateDoc,
    addDoc
} from "firebase/firestore";

// --- KONFIGURASI FIREBASE ---
const FIREBASE_CONFIG = {
  apiKey: process.env.REACT_APP_FIREBASE_KEY, 
  authDomain: process.env.REACT_APP_FIREBASE_DOMAIN || "vdvoucher.firebaseapp.com",
  projectId: process.env.REACT_APP_FIREBASE_PROJECT_ID || "vdvoucher", 
  storageBucket: process.env.REACT_APP_FIREBASE_STORAGE || "vdvoucher.firebasestorage.app",
  messagingSenderId: process.env.REACT_APP_FIREBASE_SENDER || "535315980318",
  appId: process.env.REACT_APP_FIREBASE_APP_ID || "1:535315980318:web:ac71d91380d51f1a7ace0f"
};

// --- NAMA KOLEKSI ---
const DB_COLLECTION_NAME = 'extracted_vouchers'; 
const REKAPAN_COLLECTION = 'rekapan_operasional';
const AGENTS_COLLECTION = 'daftar_agen'; 

// --- CONSTANTS ---
// Menambahkan variabel webhook ID sesuai instruksi yang diingat [2025-12-19]
export const WEBHOOK_ID = process.env.REACT_APP_WEBHOOK_ID || "WH-AGENTS-UPDATE-2026"; 

// --- INISIALISASI FIREBASE ---
const app = initializeApp(FIREBASE_CONFIG);
export const db = getFirestore(app);

/**
 * ==========================================
 * FUNGSI UNTUK DAFTAR AGEN (DaftarAgen.js)
 * ==========================================
 */

/**
 * Mengambil semua data agen untuk ditampilkan di UI
 */
export async function getAgents() {
    try {
        const q = query(collection(db, AGENTS_COLLECTION), orderBy("name", "asc"));
        const querySnapshot = await getDocs(q);
        return querySnapshot.docs.map(doc => ({ 
            id: doc.id, 
            ...doc.data() 
        }));
    } catch (err) {
        console.error("Error fetching agents:", err);
        throw err;
    }
}

/**
 * Menyimpan agen baru atau memperbarui saldo agen lama.
 * Fungsi ini krusial untuk sinkronisasi upload Excel.
 */
export async function saveAgent(agentData) {
    try {
        const { id, ...data } = agentData;
        
        // Jika ID ada dan merupakan string Firestore, lakukan UpdateDoc
        if (id && typeof id === 'string' && id.length > 15) {
            const docRef = doc(db, AGENTS_COLLECTION, id);
            await updateDoc(docRef, {
                ...data,
                lastUpdated: serverTimestamp(),
                webhookId: WEBHOOK_ID
            });
            return id;
        } else {
            // Jika agen benar-benar baru, lakukan AddDoc
            const docRef = await addDoc(collection(db, AGENTS_COLLECTION), {
                ...data,
                createdAt: serverTimestamp(),
                webhookId: WEBHOOK_ID
            });
            return docRef.id;
        }
    } catch (err) {
        console.error("Error saving agent:", err);
        throw err;
    }
}

/**
 * Menghapus data agen secara permanen
 */
export async function deleteAgent(agentId) {
    try {
        await deleteDoc(doc(db, AGENTS_COLLECTION, agentId));
    } catch (err) {
        console.error("Error deleting agent:", err);
        throw err;
    }
}

/**
 * ==========================================
 * FUNGSI PENDUKUNG LAINNYA
 * ==========================================
 */

export async function saveRekapData(date, data, showStatus) {
    try {
        const docRef = doc(db, REKAPAN_COLLECTION, date);
        await setDoc(docRef, {
            ...data,
            lastUpdated: serverTimestamp()
        }, { merge: true });
        
        if (showStatus) showStatus("Data tersinkronisasi", "success");
        return { success: true };
    } catch (err) {
        if (showStatus) showStatus(`Gagal: ${err.message}`, 'error');
        throw err;
    }
}

export async function saveCodesToDatabase(codes, filename, showStatus) {
    try {
        const docId = `extraction_${Date.now()}`;
        const docRef = doc(db, DB_COLLECTION_NAME, docId);
        await setDoc(docRef, {
            codes: codes,
            filename: filename,
            timestamp: serverTimestamp(),
            webhookId: WEBHOOK_ID
        });
        return { success: true, id: docId };
    } catch (err) {
        if (showStatus) showStatus(`Gagal menyimpan: ${err.message}`, 'error');
        throw err;
    }
}

export async function fetchHistory() {
    try {
        const q = query(collection(db, DB_COLLECTION_NAME), orderBy("timestamp", "desc"));
        const querySnapshot = await getDocs(q);
        return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
    } catch (err) {
        console.error("Error fetching history:", err);
        throw err;
    }
}

export async function updateFilename(itemId, newFilename) {
    try {
        const docRef = doc(db, DB_COLLECTION_NAME, itemId);
        await updateDoc(docRef, { filename: newFilename.trim() });
        return { success: true };
    } catch (err) {
        console.error("Error update filename:", err);
        throw err;
    }
}

export async function deleteHistoryItem(itemId) {
    try {
        await deleteDoc(doc(db, DB_COLLECTION_NAME, itemId));
        return { success: true };
    } catch (err) {
        console.error("Error delete history:", err);
        throw err;
    }
}